source='''def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out
    h, w = len(grid), len(grid[0])
    def nearby_count(marker):
        r0, c0 = marker
        return sum(1 for r in range(max(0, r0-4), min(h, r0+5))
                   for c in range(max(0, c0-4), min(w, c0+5))
                   if grid[r][c] not in (0, 5))
    source, target = sorted(markers, key=nearby_count, reverse=True)[:2]
    sr, sc = source
    tr, tc = target
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value not in (0, 5):
                rr, cc = tr + r - sr, tc + c - sc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    out[tr][tc] = 0
    return out
'''
